import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph: Lessons Learned from Emergency Support - Joachim Kraftmayer, Clyso GmbH","description":"","frontmatter":{"title":"Ceph: Lessons Learned from Emergency Support - Joachim Kraftmayer, Clyso GmbH","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","紧急支持","高可用性","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_-_Lessons_Learned_from_Emergency_Support_-_Joachim_Kraftmayer_Clyso_GmbH.md","filePath":"posts/2023/Ceph_-_Lessons_Learned_from_Emergency_Support_-_Joachim_Kraftmayer_Clyso_GmbH.md","lastUpdated":1780459816000}'),l={name:"posts/2023/Ceph_-_Lessons_Learned_from_Emergency_Support_-_Joachim_Kraftmayer_Clyso_GmbH.md"};function i(s,a,n,h,_,m){return r(),o("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-紧急支持中的经验教训" tabindex="-1">会议主题：紧急支持中的经验教训 <a class="header-anchor" href="#会议主题-紧急支持中的经验教训" aria-label="Permalink to &quot;会议主题：紧急支持中的经验教训&quot;">​</a></h4><h4 id="主讲人-joachim-kraftmayer-clyso-gmbh" tabindex="-1">主讲人：Joachim Kraftmayer，Clyso GmbH <a class="header-anchor" href="#主讲人-joachim-kraftmayer-clyso-gmbh" aria-label="Permalink to &quot;主讲人：Joachim Kraftmayer，Clyso GmbH&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Ceph使用案例和经验分享</strong>：</p><ul><li>Joachim Kraftmayer分享了Ceph在过去两三年中的多种应用案例，强调了其在虚拟环境、大型集群和超大规模环境中的多样性。</li><li>讨论了Ceph在不同硬件和部署工具中的应用，如VMware、OpenStack、DeepSea、SaltStack、Ansible等。</li></ul></li><li><p><strong>具体案例分析</strong>：</p><ul><li><strong>性能问题</strong>：一个仅含三个OSD的集群因使用较旧的Ceph版本（Luminous）而出现性能问题。</li><li><strong>配置和管理问题</strong>：强调了PG（Placement Groups）的重要性，并讨论了如何在不中断服务的情况下动态调整集群配置。</li><li><strong>硬件和网络问题</strong>：指出消费者级SSD、桌面旋转磁盘、CPU功率不足和网络接口带宽瓶颈等问题。</li></ul></li><li><p><strong>功能和配置建议</strong>：</p><ul><li><strong>MDS服务</strong>：建议根据负载合理配置MDS数量，避免过度配置。</li><li><strong>PG Auto Scaler</strong>：建议禁用自动缩放，手动预定义PG数量以确保性能。</li><li><strong>缓存层</strong>：不建议使用RBD缓存层，因其不稳定且难以管理。</li></ul></li><li><p><strong>数据恢复和备份策略</strong>：</p><ul><li>强调了备份策略的重要性，尤其是在生产环境中。</li><li>讨论了数据恢复的复杂性和潜在风险，特别是在使用大容量磁盘时。</li></ul></li><li><p><strong>操作和管理建议</strong>：</p><ul><li>建议定期进行硬件和性能测试，以确保集群的健康运行。</li><li>强调了在生产环境中进行彻底测试的重要性，避免盲目信任自动配置。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>社区和培训</strong>：计划在德国组织Ceph日活动，以加强与社区的联系并分享生产经验。</li><li><strong>硬件和配置优化</strong>：继续研究和优化Ceph在不同硬件和配置下的性能。</li><li><strong>备份和恢复策略</strong>：为生产环境制定和实施更有效的备份和恢复策略。</li></ul><h4 id="会议反馈和讨论" tabindex="-1">会议反馈和讨论： <a class="header-anchor" href="#会议反馈和讨论" aria-label="Permalink to &quot;会议反馈和讨论：&quot;">​</a></h4><ul><li>与会者就MDS数量、PG配置、硬件选择等问题进行了深入讨论。</li><li>主讲人强调了Ceph在大型集群中的应用和管理挑战，以及如何通过合理的配置和策略来应对这些挑战。</li></ul><h4 id="结束语" tabindex="-1">结束语： <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语：&quot;">​</a></h4><ul><li>Joachim Kraftmayer感谢与会者的参与，并鼓励大家继续关注Ceph的发展和最佳实践。</li></ul>',11)])])}const u=e(l,[["render",i]]);export{c as __pageData,u as default};
